===================================================================
--- 
+++ 
@@ -0,0 +1,34 @@
+
+
+
+/* Glow effect for each rounded box – corners + edges (mirrors .glow::before) */
+.rounded-box::before {
+  content: "";
+  position: absolute;
+  inset: -20px; /* extend beyond edges for softness */
+  pointer-events: none;
+  z-index: 0;
+  border-radius: inherit;
+  filter: blur(var(--blur));
+  opacity: 1;
+  /* Use percentage-based radii so it scales with the box size */
+  background:
+    /* Corners */
+    radial-gradient(70% 70% at 0% 0%,     rgba(var(--glow-top-left), var(--alpha-corner-top-left)) 0%, rgba(var(--glow-top-left), 0) 60%),
+    radial-gradient(70% 70% at 100% 0%,   rgba(var(--glow-top-right), var(--alpha-corner-top-right)) 0%, rgba(var(--glow-top-right), 0) 60%),
+    radial-gradient(70% 70% at 0% 100%,   rgba(var(--glow-bottom-left), var(--alpha-corner-bottom-left)) 0%, rgba(var(--glow-bottom-left), 0) 60%),
+    radial-gradient(70% 70% at 100% 100%, rgba(var(--glow-bottom-right), var(--alpha-corner-bottom-right)) 0%, rgba(var(--glow-bottom-right), 0) 60%),
+    /* Edges */
+    radial-gradient(60% 50% at 50% 0%,    rgba(var(--glow-top), var(--alpha-edge-top)) 0%, rgba(var(--glow-top), 0) 60%),
+    radial-gradient(60% 50% at 50% 100%,  rgba(var(--glow-bottom), var(--alpha-edge-bottom)) 0%, rgba(var(--glow-bottom), 0) 60%),
+    radial-gradient(50% 60% at 0% 50%,    rgba(var(--glow-left), var(--alpha-edge-left)) 0%, rgba(var(--glow-left), 0) 60%),
+    radial-gradient(50% 60% at 100% 50%,  rgba(var(--glow-right), var(--alpha-edge-right)) 0%, rgba(var(--glow-right), 0) 60%);
+}
+
+.rounded-box {
+  position: relative;
+  isolation: isolate;
+  /* Optional per-box tuning */
+  --blur: 40px; /* override page blur just for the box */
+  /* --alpha-edge-top: 0.7; etc. (you can override any of the root vars per box) */
+}
